package com.example.mail;

import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import org.springframework.boot.context.properties.ConfigurationProperties;
import org.springframework.validation.annotation.Validated;

@ConfigurationProperties(prefix = "app.mail")
@Validated
public class MailProperties {

    @NotBlank
    private String host;

    @Min(1)
    private int port = 465;

    private String from;

    public String getHost() {
        return host;
    }

    public void setHost(String host) {
        this.host = host;
    }

    public int getPort() {
        return port;
    }

    public void setPort(int port) {
        this.port = port;
    }

    public String getFrom() {
        return from;
    }

    public void setFrom(String from) {
        this.from = from;
    }
}

package com.example.mail;

import org.springframework.boot.context.properties.EnableConfigurationProperties;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

@Configuration
@EnableConfigurationProperties(MailProperties.class)
public class MailConfig {

    @Bean
    public MailService mailService(MailProperties properties) {
        // 属性对象本身就是一个 Bean，构造器注入即可使用
        return new MailService(properties.getHost(), properties.getPort());
    }
}

class MailService {
    private final String host;
    private final int port;

    MailService(String host, int port) {
        this.host = host;
        this.port = port;
    }

    void send(String to) {
        System.out.println("connect " + host + ":" + port + " -> " + to);
    }
}
